// 1. PROFILE:  node --cpu-prof app.js   (or the Chrome DevTools Performance
//    panel). For the real cost in Node, look at GC:
//    node --trace-gc app.js          // GC pauses are often the dominant cost
//    Chrome: DevTools > Memory > allocation sampling

// 3. ONE CHANGE at the measured hotspot. The JavaScript wins are usually:
//    - SHAPE STABILITY: build objects the same way every time so the hidden
//      class is shared and the access site stays monomorphic.
function makeA(x) { return { x: x, y: 0 }; }   // {x, y}
function makeB(x) { return { y: 0, x: x }; }   // {y, x}  <-- DIFFERENT hidden class

//    - allocation in the loop (the GC pause is the cost):
//      hoist, reuse, or move to a typed array
const xs = new Float64Array(n);                 // contiguous, no per-element boxing

